import re
PICKUP=r'F-?150|F-?250|F-?350|SILVERADO|SIERRA|RAM 1500|RAM 2500|RAM 3500|RAM PICKUP|1500 CREW|1500 QUAD|2500|TACOMA|TUNDRA|FRONTIER|RANGER|COLORADO|CANYON|GLADIATOR|RIDGELINE|TITAN|MAVERICK|SANTA CRUZ|CYBERTRUCK|R1T|LIGHTNING|SUPERCREW|SUPERCAB|CREW CAB|DOUBLE CAB|ACCESS CAB|KING CAB|REGULAR CAB|EXTENDED CAB|QUAD CAB|MEGA CAB'
VAN=r'ODYSSEY|SIENNA|PACIFICA|CARAVAN|CARNIVAL|SEDONA|QUEST|TRANSIT|PROMASTER|EXPRESS|SAVANA|SPRINTER|METRIS|VOYAGER|TOWN & COUNTRY|TOWN AND COUNTRY'
EV=r'^TESLA|BOLT|LEAF|IONIQ 5|IONIQ 6|MACH-E|MUSTANG MACH|ID\.4|ID4|EV6|EV9|NIRO EV|KONA ELECTRIC|E-TRON|TAYCAN|I3|I4|IX|POLESTAR|RIVIAN|LUCID|EQS|EQE|EQB|SOLTERRA|BZ4X|LYRIQ|EQUINOX EV|BLAZER EV|PROLOGUE|ZDX|ARIYA|HUMMER EV|SILVERADO EV|LIGHTNING|E-GOLF|IONIQ ELECTRIC|SOUL EV|FIAT 500E|CLARITY'
SUV=r'ROGUE|EQUINOX|CR-V|CRV|RAV4|ESCAPE|EXPLORER|CHEROKEE|COMPASS|WRANGLER|RENEGADE|TUCSON|SANTA FE|SPORTAGE|SORENTO|TELLURIDE|PALISADE|HIGHLANDER|4RUNNER|PILOT|PASSPORT|HR-V|HRV|EDGE|TRAVERSE|TAHOE|SUBURBAN|TRAX|TRAILBLAZER|BLAZER|MODEL Y|MODEL X|X1|X2|X3|X4|X5|X6|X7|GLA|GLB|GLC|GLE|GLS|G-CLASS|Q3|Q5|Q7|Q8|FORESTER|ASCENT|CROSSTREK|OUTBACK|CX-|MURANO|PATHFINDER|KICKS|ARMADA|DURANGO|JOURNEY|ATLAS|TIGUAN|TAOS|BRONCO|EXPEDITION|ACADIA|TERRAIN|YUKON|ENVISION|ENCORE|ENCLAVE|XT4|XT5|XT6|ESCALADE|MDX|RDX|NX|RX|GX|LX|UX|KONA|VENUE|SELTOS|NIRO|SOUL|ECOSPORT|SEQUOIA|LAND CRUISER|VENZA|COROLLA CROSS|C-HR|CHR|ECLIPSE CROSS|OUTLANDER|MACAN|CAYENNE|XC40|XC60|XC90|RANGE ROVER|DISCOVERY|DEFENDER|EVOQUE|VELAR|F-PACE|E-PACE|STELVIO|MKC|MKX|NAUTILUS|CORSAIR|AVIATOR|NAVIGATOR|QX|ROGUE SPORT|MIRAGE G4|HORNET|TONALE|CX30|CX50|CX5|CX9|CX90|TRAILHAWK|COMMANDER|WAGONEER|ENCORE GX|TRAX|BX|GV70|GV80|GV60|SANTA|BLAZER'
def segment(make, model, code):
    m=f"{make} {model}".upper()
    if re.search(EV,m) or re.search(EV, (model or '').upper()): ev=True
    else: ev=False
    if re.search(PICKUP,m): s='Pickup'
    elif re.search(VAN,m): s='Van/Minivan'
    elif re.search(SUV,m): s='SUV/Crossover'
    elif code=='2': s='Pickup'
    elif code=='3': s='SUV/Crossover'
    else: s='Car'
    return s, ev
